contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint initialCredit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(initialCredit == 0);
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);

        uint cBalBefore = address(c).balance;
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint testBalBefore = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint testBalAfter = address(this).balance;

        assert(address(c).balance == cBalBefore && testBalAfter >= testBalBefore + depositAmount);
    }

    receive() external payable {}
}

