// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, uint256 initialCredit) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        initialCredit = 0;
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        uint cBalBefore = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint testBalBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint testBalAfter = address(this).balance;
        assertTrue(address(c).balance == cBalBefore && testBalAfter >= testBalBefore + depositAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 initialCredit) public {
        _run(depositAmount, initialCredit);
    }

    receive() external payable {}
}
